#include <string.h>
#include "cm_display_sleep_lifecycle_check.h"
#include "cm_display_sleep_lifecycle_vectors.h"
uint16_t cm_display_sleep_lifecycle_check(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){uint16_t f,patch,end,failures=0;cm_native_io io,old;if(n>=64u)return 1;cm_display_sleep_lifecycle_input(s,&io,(uint16_t)(cm_display_sleep_lifecycle_numbers[n]/4u));memcpy(before,s,sizeof *s);old=io;{uint8_t phase;uint16_t status=0;for(phase=0;phase<=cm_display_sleep_lifecycle_numbers[n]%4u;++phase)status=cm_display_sleep_lifecycle_apply(s,&io,phase);if(status!=cm_display_sleep_lifecycle_results[n])++failures;}patch=cm_display_sleep_lifecycle_offsets[n];end=cm_display_sleep_lifecycle_offsets[n+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:old.channel11;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:io.channel11;if(patch<end&&cm_display_sleep_lifecycle_patch[patch][0]==f)expected=cm_display_sleep_lifecycle_patch[patch++][1];if(actual!=expected)++failures;}if(patch!=end)++failures;old.superbank=io.superbank;old.interrupt_enabled=io.interrupt_enabled;old.channel11=io.channel11;if(memcmp(&old,&io,sizeof io))++failures;return failures;}
